<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
using namespace std;

#define vec vector
#define pb push_back
#define FOR(i, a, b) for(int i = (a); i < (b); i++)
#define FORE(i, a, b) for(int i = (a); i <= (b); i++)
#define FORD(i, a, b) for(int i = (a); i >= (b); i--)
const long long INF64 = 1e18;
typedef long long ll;

struct Edge {
  int from;
  int to;
  int f;
  int cost;

  Edge() {};

  Edge(int _from, int _to, int _f, int _cost) 
    : from(_from), to(_to), f(_f), cost(_cost) {};
};

vec<Edge> e;

const int N = 1e6 + 7;
vec<int> g[N];

ll ans = 0;
ll dist[N];
int pred[N];
int pe[N];
int inq[N];

int source = N - 2;
int target = N - 1;

int residualCapacity(int x) {
  return e[x].to - e[x].f;
}

void dijkstra() {
  FOR(i, 0, N) {
    dist[i] = INF64;
    pred[i] = -1;
    pe[i] = -1;
    inq[i] = 0;
  }
  dist[source] = 0;
  queue<int> q;
  q.push(source);
  inq[source] = 1;
  while (!q.empty()) {
    int k = q.front(); q.pop();
    inq[k] = 0;
    for (auto x : g[k]) {
      if (!residualCapacity(x)) {
        continue;
      }
      int cost = e[x].cost;
      int y = e[x].from;
      if (dist[y] > dist[k] + cost) {
        dist[y] = dist[k] + cost;
        pred[y] = k;
        pe[y] = x;
        if (inq[y] == 0) {
          inq[y] = 1;
          q.push(y);
        }
      }
    }
  }
}

void pushFlow() {
  dijkstra();
  int cur = target;
  //vec<int> zz(1, cur);
  while (cur != source) {
    e[pe[cur]].f++;
    e[pe[cur] ^ 1].f--;
    cur = pred[cur];
    //zz.push_back(cur);
  }
  //reverse(zz.begin(), zz.end());
  //for (auto x : zz) {cerr << x << " ";}
  //cerr << "\n";
  ans += dist[target];
}

void addEdge(int x, int y, int capacity, int cost) {
  g[x].push_back(e.size());
  e.push_back(Edge(y, capacity, 0, cost));
  g[y].push_back(e.size());
  e.push_back(Edge(x, 0, 0, -cost));
}

int n, m, k, c, d;
int timeLayers = 101;

void inputAndBuildGraph() {
  //freopen("??.in", "r", stdin);
  //freopen("??.out", "w", stdout);
  scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
  FOR(i, 0, k) {
    int x;
    scanf("%d", &x);
    --x;
    addEdge(source, x, 1, 0);
  }
  FOR(i, 0, timeLayers) {
    addEdge(i * n, target, k, i * c);
  }
  FOR(i, 0, m) {
    int x, y;
    scanf("%d %d", &x, &y);
    --x, --y;
    FOR(i, 0, timeLayers - 1) FOR(j, 0, k) {
      addEdge(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
    }
    FOR(i, 0, timeLayers - 1) FOR(j, 0, k) {
      addEdge(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
    }
  }
}

void solve() {
  FOR(i, 0, n) FOR(j, 0, timeLayers - 1) {
    addEdge(i + j * n, i + j * n + n, k, 0);
  }
  FOR(i, 0, k) {
    pushFlow();
  }
  printf("%lld\n", ans);

  // read the question correctly (is y a vowel?)
  // look out for SPECIAL CASES (n=1?) and overflow (ll vs int?)
}

int main() {
  //auto beginProgram = chrono::steady_clock::now();
  {
    inputAndBuildGraph();
    solve();
  }
  //auto endProgram = chrono::steady_clock::now();

  return 0;
}


